332	/**
333	 * Bulk invite. The seat quota is checked once for the whole batch — inviting
334	 * five people into a plan with three free seats must fail as a batch rather
335	 * than half-succeeding — and the rate limit is charged per invite.
336	 */
337	export async function inviteMembers(
338	  actor: Actor,
339	  input: InviteMembersInput,
340	): Promise<readonly Invitation[]> {
341	  assertOrgScope(actor, input.orgId);
342	  assertCan(actor, "member:invite", orgResource(input.orgId));
343	
344	  const verdict = await consumeRateLimit(
345	    input.orgId,
346	    INVITE_BUCKET,
347	    input.invites.length,
348	  );
349	  if (!verdict.allowed) {
350	    throw new Error(
351	      `Invite rate limit reached; try again after ${verdict.resetAt}`,
352	    );
353	  }
354	
355	  const org = requireFound(
356	    await orgRepo.findOrgById(input.orgId),
357	    "Organization",
358	    input.orgId,
359	  );
360	
361	  const seatsUsed =
362	    (await memberRepo.countActiveMembers(input.orgId)) +
363	    (await invitationRepo.countPendingInvitations(input.orgId));
364	
365	  if (
366	    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
367	  ) {
368	    const limits = getPlanLimits(org.plan);
369	    throw new Error(
370	      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
371	    );
372	  }
373	
374	  const invitations: Invitation[] = [];
375	
376	  for (const invite of input.invites) {
377	    const token = randomToken(32);
378	    const invitation = await invitationRepo.insertInvitation(
379	      input.orgId,
380	      {
381	        orgId: input.orgId,
382	        email: invite.email,
383	        role: invite.role,
384	        expiresInDays: DEFAULT_EXPIRY_DAYS,
385	      },
386	      actor.userId,
387	      hashToken(token),
388	    );
389	
390	    invitations.push(invitation);
391	
392	    await emit("member.invited", {
393	      orgId: input.orgId,
394	      actorId: actor.userId,
395	      occurredAt: invitation.createdAt,
396	      email: invite.email,
397	      role: invite.role,
398	    });
399	  }
400	
401	  return invitations;
402	}
