408	export async function acceptInvitation(
409	  userId: UserId,
410	  input: AcceptInvitationTokenInput,
411	): Promise<Member> {
412	  const invitation = requireFound(
413	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
414	    "Invitation",
415	    "token",
416	  );
417	
418	  if (invitation.revokedAt !== null) {
419	    throw new Error("That invitation has been revoked");
420	  }
421	  if (invitation.acceptedAt !== null) {
422	    throw new Error("That invitation has already been accepted");
423	  }
424	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
425	    throw new Error("That invitation has expired");
426	  }
427	
428	  const existing = await memberRepo.findMember(invitation.orgId, userId);
429	  if (existing) return existing;
430	
431	  const member = await memberRepo.insertMember(
432	    invitation.orgId,
433	    userId,
434	    invitation.role,
435	    invitation.invitedBy,
436	  );
437	
438	  await invitationRepo.markInvitationAccepted(
439	    invitation.orgId,
440	    invitation.id,
441	    toIsoTimestamp(new Date()),
442	  );
443	
444	  await emit("member.joined", {
445	    ...envelope(invitation.orgId, userId),
446	    memberId: member.id,
447	    userId,
448	    role: member.role,
449	  });
450	
451	  return member;
452	}
