529	/**
530	 * Writes one notification row per recipient, each with the channel set that
531	 * recipient's preferences allow. A recipient who has muted every channel is
532	 * skipped entirely rather than given a row nobody will ever see.
533	 */
534	export async function notify(
535	  orgId: OrgId,
536	  kind: NotificationKind,
537	  recipients: readonly UserId[],
538	  payload: NotificationPayload,
539	): Promise<readonly Notification[]> {
540	  if (recipients.length === 0) return [];
541	
542	  const org = await orgRepo.findOrgById(orgId);
543	  const flags: FlagContext = {
544	    orgId,
545	    userId: payload.actorId,
546	    plan: org?.plan ?? "free",
547	    role: null,
548	    overrides: org?.settings.enabledFlagOverrides,
549	  };
550	
551	  const rows = [];
552	
553	  for (const recipientId of new Set(recipients)) {
554	    if (recipientId === payload.actorId) continue;
555	
556	    const preference = await preferenceRepo.getPreference(
557	      orgId,
558	      recipientId,
559	      kind,
560	    );
561	    const channels = resolveChannels(preference, flags);
562	    if (channels.length === 0) continue;
563	
564	    rows.push({
565	      orgId,
566	      recipientId,
567	      kind,
568	      title: payload.title,
569	      body: payload.body,
570	      href: payload.href,
571	      actorId: payload.actorId,
572	      channels,
573	    });
574	  }
575	
576	  return notificationRepo.insertNotifications(orgId, rows);
577	}
