639	/**
640	 * Turns a stored preference into the channels one notification will use.
641	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
642	 * the email channel additionally requires the org's `digest_email` plan flag.
643	 */
644	export function resolveChannels(
645	  preference: NotificationPreference | null,
646	  flags: FlagContext,
647	): readonly NotificationChannel[] {
648	  if (preference === null) return DEFAULT_CHANNELS;
649	
650	  const channels: NotificationChannel[] = [];
651	  if (preference.inApp) channels.push("in_app");
652	
653	  const emailAllowed =
654	    preference.email &&
655	    (!preference.digestOnly || isEnabled("digest_email", flags));
656	
657	  if (emailAllowed) channels.push("email");
658	  return channels;
659	}
