811	/** Groups a feed page by calendar day, newest day first. */
812	export function groupByDay(
813	  events: readonly ActivityEvent[],
814	): readonly ActivityGroup[] {
815	  const byDay = new Map<string, ActivityEvent[]>();
816	
817	  for (const event of events) {
818	    const day = event.occurredAt.slice(0, 10);
819	    const bucket = byDay.get(day) ?? [];
820	    bucket.push(event);
821	    byDay.set(day, bucket);
822	  }
823	
824	  return [...byDay.entries()]
825	    .sort(([a], [b]) => (a < b ? 1 : -1))
826	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
827	}
