 * for `DELETED_WORKSPACE_RETENTION_DAYS`; its owner can restore it inside the
 * window, and the retention sweep purges it once the window has closed.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import {
  activityEvents,
  getDb,
  members,
  organizations,
  organizationUsage,
  projects,
  subscriptions,
  users,
  webhookDeliveries,
} from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import { registerActivityListeners } from "@/server/services/activity-service";
import { acceptInvitation } from "@/server/services/invitation-service";
import { notify } from "@/server/services/notification-service";
import {
  createOrganization,
  deleteOrganization,
  listOrganizationsForUser,
  restoreOrganization,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
let counter = 0;

async function freshTenant(): Promise<Tenant> {
  counter += 1;
  const tenant = await createTenant(`doomed-${counter}`);
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function remove(tenant: Tenant): Promise<void> {
  await deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

/** Rewrites the deletion stamp, as if the workspace had been deleted earlier. */
function backdateDeletion(orgId: OrgId, deletedAt: Date): void {
  getDb()
    .update(organizations)
    .set({ archivedAt: deletedAt.toISOString() })
    .where(eq(organizations.id, orgId))
    .run();
}

function principalFor(userId: UserId) {
  return {
    userId,
    email: "someone@example.test",
    activeOrgId: null,
    expiresAt: new Date(Date.now() + MS_PER_DAY).toISOString() as never,
  };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("deleting a workspace", () => {
  it("publishes organization.deleted and records it in the audit log", async () => {
    const tenant = await freshTenant();
    detachers.push(registerActivityListeners());
    const seen: unknown[] = [];
    detachers.push(subscribe("organization.deleted", (payload) => void seen.push(payload)));

    await remove(tenant);

    expect(seen).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.owner,
        slug: tenant.org.slug,
      }),
    ]);

    const audit = getDb()
      .select()
      .from(activityEvents)
      .where(eq(activityEvents.orgId, tenant.org.id))
      .all();
    expect(audit).toEqual([
      expect.objectContaining({
        action: "organization.deleted",
        subjectKind: "organization",
        subjectId: tenant.org.id,
        actorId: tenant.userIds.owner,
      }),
    ]);
  });

  it("refuses to delete a workspace twice", async () => {
    const tenant = await freshTenant();
    await remove(tenant);
    await expect(remove(tenant)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("a deleted workspace", () => {
  it("cannot be signed in to, is not listed, and keeps its slug reserved", async () => {
    const tenant = await freshTenant();
    await remove(tenant);

    await expect(
      resolveActorForOrg(principalFor(tenant.userIds.owner), tenant.org.slug),
    ).resolves.toBeNull();
    await expect(listOrganizationsForUser(tenant.userIds.owner)).resolves.toEqual([]);

    const other = await createOrganization(tenant.userIds.owner, {
      name: "Copycat",
      slug: tenant.org.slug,
      plan: "free",
    });
    expect(other.slug).not.toBe(tenant.org.slug);
  });

  it("receives no notifications and accepts no invitations", async () => {
    const tenant = await freshTenant();
    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "new@example.test", role: "member", expiresInDays: 7 },
      tenant.userIds.owner,
      hashToken("join-me"),
    );
    const joiner = await userRepo.insertUser({
      email: `joiner-${counter}@example.test`,
      name: "Joiner",
      passwordHash: "seed",
    });
    await remove(tenant);

    await expect(
      notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], {
        title: "t",
        body: "b",
        href: "/",
        actorId: null,
      }),
    ).resolves.toEqual([]);

    await expect(acceptInvitation(joiner.id, { token: "join-me" })).rejects.toBeInstanceOf(
      NotFoundError,
    );
    const invitation = await invitationRepo.findInvitationByTokenHash(hashToken("join-me"));
    expect(invitation?.acceptedAt).toBeNull();

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    await expect(acceptInvitation(joiner.id, { token: "join-me" })).resolves.toMatchObject({
      orgId: tenant.org.id,
      userId: joiner.id,
    });
  });

  it("is left alone by the background jobs", async () => {
    const tenant = await freshTenant();
    await issueRepo.insertIssue(
      {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        title: "Late",
        description: null,
        status: "todo",
        priority: "none",
        assigneeId: tenant.userIds.member,
        parentId: null,
        estimate: null,
        dueAt: "2020-01-01T00:00:00.000Z" as never,
        labelIds: [],
      },
      tenant.userIds.owner,
    );
    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: tenant.org.id, url: "https://example.test/hook", eventTypes: ["issue.created"] },
      "secret",
    );
    const delivery = await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );
    const usageBefore = await usageRepo.getUsage(tenant.org.id);
    await remove(tenant);

    const overdue: unknown[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        if (payload.orgId === tenant.org.id) overdue.push(payload);
      }),
    );

    const now = new Date();
    await runOverdueIssueJob(now);
    await runUsageRollupJob(now);
    await runWebhookDeliveryJob(now);
    await runCleanupArchivedJob(now);

    expect(overdue).toEqual([]);
    await expect(usageRepo.getUsage(tenant.org.id)).resolves.toEqual(usageBefore);
    expect(
      getDb().select().from(webhookDeliveries).where(eq(webhookDeliveries.id, delivery.id)).get(),
    ).toMatchObject({ status: "failed", deliveredAt: null });
    await expect(orgRepo.findOrgById(tenant.org.id)).resolves.not.toBeNull();

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    await runOverdueIssueJob(now);
    expect(overdue).toHaveLength(1);
  });
});

describe("restoring a workspace", () => {
  it("brings it back and publishes organization.restored", async () => {
    const tenant = await freshTenant();
    await remove(tenant);
    const seen: unknown[] = [];
    detachers.push(subscribe("organization.restored", (payload) => void seen.push(payload)));

    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    expect(restored.archivedAt).toBeNull();
    expect(seen).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.owner,
        slug: tenant.org.slug,
      }),
    ]);
    await expect(
      resolveActorForOrg(principalFor(tenant.userIds.owner), tenant.org.slug),
    ).resolves.toMatchObject({ orgId: tenant.org.id, role: "owner" });
    await expect(listOrganizationsForUser(tenant.userIds.owner)).resolves.toHaveLength(1);
  });

  it("is owner-only, and invisible to non-members", async () => {
    const tenant = await freshTenant();
    const stranger = await freshTenant();
    await remove(tenant);

    await expect(
      restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      restoreOrganization(stranger.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      restoreOrganization(tenant.userIds.owner, "01HZZZZZZZZZZZZZZZZZZZZZZZ" as OrgId),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const tenant = await freshTenant();
    const seen: unknown[] = [];
    detachers.push(subscribe("organization.restored", (payload) => void seen.push(payload)));

    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).resolves.toEqual(tenant.org);
    expect(seen).toEqual([]);
  });

  it("is refused once the window has closed, purged or not", async () => {
    const tenant = await freshTenant();
    await remove(tenant);

    backdateDeletion(tenant.org.id, new Date(Date.now() - WINDOW_MS + 60_000));
    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).resolves.toMatchObject({ archivedAt: null });

    await remove(tenant);
    backdateDeletion(tenant.org.id, new Date(Date.now() - WINDOW_MS));
    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("the purge", () => {
  it("removes an expired workspace and everything it owned, and nothing else", async () => {
    const doomed = await freshTenant();
    const recent = await freshTenant();
    const live = await freshTenant();
    detachers.push(registerActivityListeners());
    await remove(doomed);
    await remove(recent);

    const now = new Date();
    backdateDeletion(doomed.org.id, new Date(now.getTime() - WINDOW_MS));
    backdateDeletion(recent.org.id, new Date(now.getTime() - WINDOW_MS + 1));

    await runCleanupArchivedJob(now);

    const db = getDb();
    for (const table of [members, projects, subscriptions, activityEvents, organizationUsage]) {
      expect(db.select().from(table).where(eq(table.orgId, doomed.org.id)).all()).toEqual([]);
    }
    await expect(orgRepo.findOrgById(doomed.org.id)).resolves.toBeNull();
    expect(
      db.select().from(users).where(eq(users.id, doomed.userIds.owner)).get(),
    ).toBeDefined();
    await expect(
      restoreOrganization(doomed.userIds.owner, doomed.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    for (const kept of [recent, live]) {
      await expect(orgRepo.findOrgById(kept.org.id)).resolves.not.toBeNull();
      expect(db.select().from(members).where(eq(members.orgId, kept.org.id)).all()).toHaveLength(4);
      expect(db.select().from(projects).where(eq(projects.orgId, kept.org.id)).all()).toHaveLength(1);
    }

    const reborn = await createOrganization(doomed.userIds.owner, {
      name: "Reborn",
      slug: doomed.org.slug,
      plan: "free",
    });
    expect(reborn.slug).toBe(doomed.org.slug);
  });
});

